package com.gomgomapps.math.core;
import java.util.*;import org.junit.Test;import static org.junit.Assert.*;
public class PrimeFactorListsTest {
 private List<String> solve(int n){List<String>result=new ArrayList<>();for(int d=2;d<=n;d++)if(n%d==0){int divisors=0;for(int k=1;k<=d;k++)if(d%k==0)divisors++;if(divisors==2)result.add(""+d);}return result;}
 @Test public void all99PublicConditionsUseDistinctPrimeDivisorsNotKeys(){Set<String>signatures=new HashSet<>();for(int n=1;n<=99;n++){Question q=PrimeFactorLists.indexed(n-1);assertTrue(signatures.add(q.signature()));assertEquals(n,PrimeFactorLists.read(q));q.answers=new String[]{"poison"};q.expression="poison";List<String>solution=n==1?List.of(PrimeFactorLists.NONE):solve(n);assertTrue(PrimeFactorLists.check(q,solution).correct());assertEquals(n==1,PrimeFactorLists.noneExpected(q));assertTrue(q.choices.isEmpty());if(n>1){assertFalse(PrimeFactorLists.check(q,List.of(PrimeFactorLists.NONE)).correct());if(solution.size()>1)assertEquals(-1,PrimeFactorLists.check(q,solution.subList(0,solution.size()-1)).index);}}assertEquals(99,signatures.size());assertEquals(List.of("2","3"),solve(12));assertEquals(List.of("7"),solve(49));assertEquals(List.of("97"),solve(97));assertEquals(List.of("3","11"),solve(99));}
 @Test public void markersMissingRepeatedOrderAndInvalidValuesAreDistinct(){Question q=PrimeFactorLists.make(12);assertEquals(1,PrimeFactorLists.check(q,List.of("2","2","3")).index);assertEquals(1,PrimeFactorLists.check(q,List.of("3","2")).index);assertEquals(0,PrimeFactorLists.check(q,List.of("4")).index);assertEquals(0,PrimeFactorLists.check(q,List.of("5")).index);assertEquals(0,PrimeFactorLists.check(q,List.of("1")).index);assertEquals(0,PrimeFactorLists.check(q,List.of("13")).index);assertEquals(Checker.Status.INPUT_NEEDED,PrimeFactorLists.check(q,List.of("")).status);assertEquals(Checker.Status.INPUT_NEEDED,PrimeFactorLists.check(q,List.of("2",PrimeFactorLists.NONE,"3")).status);assertTrue(PrimeFactorLists.check(PrimeFactorLists.make(1),List.of("garbage",PrimeFactorLists.NONE)).correct());assertEquals(Checker.Status.WRONG_ANSWER,PrimeFactorLists.check(q,List.of("2",PrimeFactorLists.NONE)).status);for(int n:new int[]{0,100}){assertEquals(-1,PrimeFactorLists.read(new Question(PrimeFactorLists.ID,n+"의 서로 다른 소인수를 모두 쓰세요.\n작은 수부터 쓰세요.","","2")));try{PrimeFactorLists.make(n);fail();}catch(IllegalArgumentException expected){}}}
 @Test public void helpDefinitionBlankAndNoListDisclosureOrTransfer(){for(int n=1;n<=99;n++){Question q=PrimeFactorLists.make(n);q.answers=new String[]{"poison"};PrimeFactorLists.attach(q);assertFalse(q.studyGuide.transfer);assertEquals(1,q.studyGuide.frames.size());HelpPlan help=HelpPlan.forQuestion(q);assertFalse(help.canTransfer());assertEquals(List.of(""),help.restore(null,q.id).entries);assertEquals("distinct-prime-factor-list-v1",q.studyGuide.teachingVersion);if(n==1){assertEquals("0",q.studyGuide.frames.get(0).expected);assertEquals(Map.of("0","소인수가 없다","1","소인수가 있다"),q.studyGuide.frames.get(0).options);}else{assertEquals("소수의 양의 약수 개수 = ",q.studyGuide.frames.get(0).before);assertEquals("2",q.studyGuide.frames.get(0).expected);assertTrue(q.studyGuide.frames.get(0).options.isEmpty());}}}
 @Test public void smallBoundIncludesNoneAndUsesFreshThenOldest(){CurriculumLimits limits=new CurriculumLimits("minGiven=1;maxGiven=5;maxResult=99;nonnegative=true");Map<String,Integer>recent=new LinkedHashMap<>();Set<Integer>seen=new HashSet<>();Random pinned=new Random(){@Override public int nextInt(int bound){return 0;}};for(int i=0;i<5;i++){Question q=PrimeFactorLists.next(pinned,limits,recent);assertTrue(seen.add(PrimeFactorLists.read(q)));recent.put(q.signature(),i);}assertEquals(Set.of(1,2,3,4,5),seen);assertEquals(0,(int)recent.get(PrimeFactorLists.next(pinned,limits,recent).signature()));}
}

